void split_into_rules(const string text, vector<rule> &rules, set<char> &non_terminal, set<char> &terminal, set<string> &right_parts) {
	//每条规则形如“左部::=右部1|右部2|...”，规则之间以空白分隔；
	//“::=”两侧以及候选式内部允许夹杂空白与换行，提取时一律忽略
	vector<string::size_type> marks;//文本中所有“::=”出现的位置
	for (string::size_type pos = text.find("::="); pos != string::npos; pos = text.find("::=", pos + 3)) {
		marks.push_back(pos);
	}
	for (unsigned int m = 0; m < marks.size(); m++) {
		//“::=”之前最近的一个非空白字符就是本条规则的左部
		string::size_type left_at = string::npos;
		for (string::size_type k = marks[m]; k > 0; k--) {
			if (!isspace((unsigned char)text[k - 1])) {
				left_at = k - 1;
				break;
			}
		}
		if (left_at == string::npos) {
			continue;//找不到左部，不是一条合法的产生式，直接忽略
		}
		char left = text[left_at];
		//右部一直延伸到下一条规则的左部之前，最后一条规则则延伸到文本末尾
		string::size_type end = text.length();
		if (m + 1 < marks.size()) {
			end = marks[m + 1];
			while (end > marks[m] + 3 && isspace((unsigned char)text[end - 1])) {
				end--;
			}
			if (end > marks[m] + 3) {
				end--;//下一条规则的左部字符不属于本条规则的右部
			}
		}
		string rights = text.substr(marks[m] + 3, end - marks[m] - 3);

		//右部按“|”切分成若干个候选式，其中的空白只起分隔作用
		vector<string> parts;
		string part = "";
		for (unsigned int i = 0; i < rights.length(); i++) {
			if (isspace((unsigned char)rights[i])) {
				continue;
			}
			if (rights[i] == '|') {
				parts.push_back(part);
				part = "";
			}
			else {
				part += rights[i];
			}
		}
		parts.push_back(part);

		//同一个非终结符的产生式可能分开书写，合并到同一条规则中
		int at = -1;
		for (unsigned int i = 0; i < rules.size(); i++) {
			if (rules[i].left == left) {
				at = (int)i;
				break;
			}
		}
		if (at < 0) {
			rule new_rule;
			new_rule.left = left;
			rules.push_back(new_rule);
			at = (int)rules.size() - 1;
		}
		for (unsigned int i = 0; i < parts.size(); i++) {
			if (!parts[i].empty()) {
				rules[at].right.push_back(parts[i]);
			}
		}
		//出现在规则左部的一定是非终结符
		non_terminal.insert(left);
	}

	//所有规则左部都收集完毕之后，再回头区分右部中的终结符和非终结符
	for (unsigned int i = 0; i < rules.size(); i++) {
		for (unsigned int j = 0; j < rules[i].right.size(); j++) {
			const string& part = rules[i].right[j];
			right_parts.insert(part);
			for (unsigned int k = 0; k < part.length(); k++) {
				char c = part[k];
				if (c == '@') {
					continue;//“@”代表空串ε，既不是终结符也不是非终结符
				}
				if (non_terminal.count(c) > 0) {
					continue;
				}
				if (isupper((unsigned char)c)) {
					non_terminal.insert(c);//大写字母一律看作非终结符
				}
				else {
					terminal.insert(c);
				}
			}
		}
	}
}
